const MES_EN = Object.fromEntries(MESES_ES.map((m, i) => [m, ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"][i]]));
const MES_CA = Object.fromEntries(MESES_ES.map((m, i) => [m, ["de gener", "de febrer", "de març", "d'abril", "de maig", "de juny", "de juliol", "d'agost", "de setembre", "d'octubre", "de novembre", "de desembre"][i]]));
